/* Housing uses the engine's country prices and purchase eligibility. */
(function(root){
'use strict';
const homes=[{id:'village_low_02',name:'Небольшой дом',size:'s',capacity:2},{id:'modest_01',name:'Компактный городской дом',size:'s',capacity:2},{id:'village_middle_01',name:'Семейный дом',size:'b',capacity:4},{id:'village_high_01',name:'Семейный дом с садом',size:'b',capacity:4}],rooms={living_room:'Гостиная',kitchen:'Кухня',bedroom:'Спальня',bathroom:'Ванная'};
const usd=n=>LifelineEconomy.toUSD(n),clampN=(n,a,b)=>Math.min(b,Math.max(a,n));
function state(){return S.lifelineHome||(S.lifelineHome={revision:0,quality:clampN((S.q||3)-2,0,3),house:homes[clampN((S.q||3)-2,0,3)].id,interiors:{}});}
function nativeItems(){try{return shopCan()?shopItems().flatMap(item=>item.opts?item.opts.map(o=>({...o,why:o.why||item.why})):item):[];}catch{return [];}}
function purchase(home){const deal=houseDeal(sovEra()?'coop':home.size),reason=self.LifelineSchedules?.reason('own_house')|| (S.age<ITEMS.house.age?'Покупка доступна с '+ITEMS.house.age+' лет':S.owns.house?'У вас уже есть дом — используйте переезд в другой':vowedHome()?'В текущем укладе жизни отдельный дом недоступен':!deal?(S.age>55?'Нужна полная стоимость без кредита':'Нужен первоначальный взнос и достаточный доход для выплат'):'');const price=deal?.price||housePrice(C())*(home.size==='s'?HOUSE_SM:houseFirstK());return {...home,price:usd(price),down:usd(deal?Math.max(0,deal.price-deal.loan-deal.help-deal.fund):price*.2),loan:usd(deal?.loan||0),disabled:!!reason,reason,condition:S.age>55?'Полная оплата':'Кредит при достаточном доходе; возможна помощь семьи'};}
function remodelOptions(room){const h=state(),valid=!!rooms[room];return homes.map((home,i)=>{const cost=Math.max(0,S.house)*.02*[.75,1,1.4,2][i],last=h.roomRepairs?.[room],reason=self.LifelineSchedules?.reason('remodel')||(!valid?'Выберите комнату':S.age<18?'Ремонт выбирают взрослые':!(S.house>0)?'Ремонт доступен для собственного жилья':last!=null&&S.age+(S.t||0)-last<1?'Эту комнату уже ремонтировали — повторно через год':S.money<cost?'Недостаточно доступных сбережений':'');return {...home,price:usd(cost),disabled:!!reason,reason};});}
function summary(){const h=state(),native=nativeItems(),others=homeOthers();return {house:h.house,capacity:homes.find(x=>x.id===h.house)?.capacity||2,residents:1+Number(others.mom)+Number(others.dad)+Number(others.pt)+others.kids.length+sibsHome().length,needsChoice:S.age>=18&&!!h.needsChoice,revision:h.revision||0,buy:homes.map(purchase),rooms:Object.entries(rooms).map(([id,name])=>({id,name,style:h.interiors?.[id]||h.house,options:remodelOptions(id)})),moves:native.filter(i=>['moveout','movehome','moveplan','bigger','smaller','sellhouse'].includes(i.id.split('@')[0])).map(i=>({id:i.id,name:text(i.n),cost:usd(i.price||0),disabled:!i.avail,reason:i.avail?'':text(i.why)||'Не выполнены условия переезда'})),pet:S.pet?{name:S.pet.n,kind:S.pet.k,here:!!petHere()}:null,pets:['d','c','h','r','b'].map(kind=>({kind,name:{d:'Собака',c:'Кошка',h:'Хомяк',r:'Кролик',b:'Попугай'}[kind],cost:usd(petCost(kind)*.25),annual:usd(petCost(kind)),disabled:!!S.pet||S.age<18||S.nomad||studyAway()||svcAway()||careNow()||S.job==='prison',reason:S.pet?'У вас уже есть питомец':S.age<18?'До 18 лет решение принимают родители':S.nomad||studyAway()||svcAway()||careNow()||S.job==='prison'?'Сейчас нет постоянного дома для питомца':''}))};}
function changeHouse(id){const home=homes.find(h=>h.id===id);if(!home)throw Error('Неизвестный дом');const old=state();S.lifelineHome={...old,house:id,quality:homes.indexOf(home),revision:(old.revision||0)+1,interiors:{},needsChoice:false};}
function perform(payload){if(S.phase!=='life'||S.pending||LifelineMoments.pending())throw Error('Сначала завершите текущий выбор');const home=homes.find(h=>h.id===payload.house);
 if(payload.mode==='select'){if(!state().needsChoice)throw Error('Выбор дома уже завершён');changeHouse(payload.house);return;}
 if(payload.mode==='buy'){if(!home)throw Error('Выберите дом');const item=purchase(home);if(item.disabled)throw Error(item.reason);const key='own_house@'+(sovEra()?'coop':home.size),allowed=nativeItems().find(x=>x.id===key&&x.avail);if(!allowed)throw Error('Условия покупки изменились');const note=buyShop(key);if(!note)throw Error('Не удалось оформить покупку');log(note,'big');changeHouse(home.id);return;}
 if(payload.mode==='move'){const item=nativeItems().find(i=>i.id===payload.action&&i.avail);if(!item||!['moveout','movehome','moveplan','bigger','smaller'].includes(item.id.split('@')[0]))throw Error('Этот переезд сейчас недоступен');const beforeMove=signature(S),note=buyShop(item.id);if(note)log(note,'big');if(S.pending||beforeMove===signature(S)&&item.id.startsWith('moveplan@')){state().preferredHome=payload.house;return;}changeHouse(payload.house);return;}
 if(payload.mode==='remodel'){const option=remodelOptions(payload.room).find(h=>h.id===payload.house);if(!option||option.disabled)throw Error(option?.reason||'Этот ремонт недоступен');const cost=LifelineEconomy.fromUSD(option.price),h=state();S.money-=cost;book('Ремонт: '+rooms[payload.room],-cost);S.house*=1.015;self.LifelineSchedules?.record('remodel');h.interiors={...h.interiors,[payload.room]:payload.house};h.roomRepairs={...h.roomRepairs,[payload.room]:S.age+(S.t||0)};h.revision=(h.revision||0)+1;eff({h:2});log('Вы обновили интерьер комнаты «'+rooms[payload.room]+'».','warm');return;}
 if(payload.mode==='pet'){const option=summary().pets.find(p=>p.kind===payload.kind);if(!option||option.disabled)throw Error(option?.reason||'Питомец сейчас недоступен');const cost=LifelineEconomy.fromUSD(option.cost);if(S.money<cost)throw Error('Недостаточно средств на обустройство для питомца');S.money-=cost;book('Всё для нового питомца',-cost);log(petAdopt(payload.kind,payload.name||''),'warm');return;}
 throw Error('Неизвестное действие дома');}
function signature(s){return JSON.stringify([s.cur,s.city,s.urban,s.flags.left,s.flags.stayHome,s.flags.oldHome,s.owns.house]);}
function after(old,command,payload){if(command==='restore'||command==='snapshot'||command==='new')return;if(command==='housing'){if(['buy','move'].includes(payload.mode))self.LifelineDetails?.memory('home','Ваш новый дом','home-'+state().revision);return;}const repaired=command==='buy'&&payload.key==='remodel'||command==='choose'&&old.pending?.id==='disaster'&&['rebuild','lifeline-rebuild-cash'].includes(payload.key)&&S.phase==='life';if(repaired){const previous=state().house,next=homes[(homes.findIndex(h=>h.id===previous)+1)%homes.length].id;changeHouse(next);state().repaired=true;return;}const fresh=(S.log||[]).slice(old.log?.length||0),moving=signature(old)!==signature(S)||command==='buy'&&['bigger','smaller','moveout','movehome','moveplan'].includes(payload.key)||fresh.some(r=>/(?:вы|ваша семья|вы с мамой|вы с вашей матерью)[^.]*переехал|ваш переезд.*состоялся/i.test(r.text));if(moving){const h=state(),q=clampN(S.q>=4||S.pct>=.8?3:S.q>=3||S.pct>=.55?2:S.q>=2||S.pct>=.25?1:0,0,3),next=homes[q].id===h.house?homes[(q+1)%homes.length].id:homes[q].id;const preferred=h.preferredHome;changeHouse(preferred&&S.age>=18?preferred:next);delete state().preferredHome;state().needsChoice=S.age>=18&&!preferred;self.LifelineDetails?.memory('home',S.age<18?'Семья переехала в новый дом':'Ваш новый дом','home-'+state().revision);}}
root.LifelineHousing={state,summary,perform,after};
})(self);
